UPDATE ar_ling_root_asl SET statement_ar = 'الشين والكاف والراء أصولٌ أربعةٌ متباينةٌ بعيدة القياس. فالأول: الشُّكر: الثَّناء على الإنسان بمعروف يُولِيكَهُ … والأصل الثاني: الامتلاء والغُزْر في الشيء … والأصل الثالث: الشَّكير من النبات، وهو الذي ينبُت من ساق الشَّجرة … والأصل الرابع: الشَّكْر، وهو النِّكاح', statement_en = 'four separate core meanings: thanks, praising someone for a kindness; being full and plentiful; new shoots growing from a tree''s trunk; and sexual union', note_md = 'Marker: أصول أربعة. Corrected: current quote is only the second aṣl; replaced with the head sentence. Was: «أصل الثاني: الامتلاء والغُزْر في الشيء». Weak-aṣl fix 2026-10-07: was «الشين والكاف والراء أصولٌ أربعةٌ متباينةٌ بعيدة القياس. فالأول: الشُّكر: الثَّناء على الإنسان بمعروف يُولِيكَهُ» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_f3d16d4d1dbf47a4 p.23. Continues in blk_mqy_1498ca1b4f95c38c p.23, blk_mqy_66fa087b4eb960c6 p.23, blk_mqy_d24d76cce5255364 p.23.', updated_at = datetime('now')
 WHERE id = 'ASL:شكر:maqayis_lugha' AND statement_ar IS 'الشين والكاف والراء أصولٌ أربعةٌ متباينةٌ بعيدة القياس. فالأول: الشُّكر: الثَّناء على الإنسان بمعروف يُولِيكَهُ';

