UPDATE ar_ling_root_asl SET statement_ar = 'القاف والصاد والدال أصولٌ ثلاثة، يدلُّ أحدها على إتيانِ شيءٍ وأَمِّه، والآخَر على اكتنازٍ في الشيء … والأصل الآخر: قَصَدْت الشيءَ كسرته … والأصل الثالث: الناقة القصيد: المكتنِزة الممتلِئة لحماً', statement_en = 'three core meanings: going to a thing and heading for it; breaking a thing; and being packed full (a she-camel full of flesh)', note_md = 'Marker: أصول ثلاثة. Corrected: old quote was an example line; head names three but lists two (breaking is the second in the body). Was: «أصل: قصَدته قَصْداً ومَقْصَداً». Primary: only book in batch Weak-aṣl fix 2026-10-07: was «القاف والصاد والدال أصولٌ ثلاثة، يدلُّ أحدها على إتيانِ شيءٍ وأَمِّه، والآخَر على اكتنازٍ في الشيء» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_c86d2487c68102f5 p.19. Continues in blk_mqy_c95f76258b0b652c p.19, blk_mqy_8faefe24c209b87e p.19.', updated_at = datetime('now')
 WHERE id = 'ASL:قصد:maqayis_lugha' AND statement_ar IS 'القاف والصاد والدال أصولٌ ثلاثة، يدلُّ أحدها على إتيانِ شيءٍ وأَمِّه، والآخَر على اكتنازٍ في الشيء';

