-- اجل
UPDATE ar_ling_root_asl SET statement_ar = 'اعلم أنّ الهمزة والجيم واللام يدلُّ على خمس كلماتٍ متباينة … فالأَجَل غاية الوقت في مَحَلِّ الدَّين وغيره … والإجْلُ: القطيع من بقر الوحش … والأجْلُ مصدر أجَلَ عليهم شَرّاً، أي جناه … والإجْل: وَجَع في العنق … والمأْجَلُ: شبه حوضٍ واسع', statement_en = 'five separate words: the end of a set time (a due date); a herd of wild cattle; bringing harm on people; a pain in the neck; and a wide basin that holds water', note_md = 'Marker: أصل (Ibn Fāris head sentence). Weak-aṣl fix 2026-10-07: was «اعلم أنّ الهمزة والجيم واللام يدلُّ على خمس كلماتٍ متباينة، لا يكادُ يمكنُ حْملُ واحدةٍ على واحدة من جهة القياس» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_8236133472a13708 p.11. Continues in blk_mqy_142ac4d1ec471246 p.11, blk_mqy_0b8418af987f914d p.11.', updated_at = datetime('now')
 WHERE id = 'ASL:اجل:maqayis_lugha' AND statement_ar IS 'اعلم أنّ الهمزة والجيم واللام يدلُّ على خمس كلماتٍ متباينة، لا يكادُ يمكنُ حْملُ واحدةٍ على واحدة من جهة القياس';

-- اني
UPDATE ar_ling_root_asl SET statement_ar = 'الهمزة والنون وما بعدهما من المعتل، لـه أصول أربعة: البُطء وما أشبهه مِن الحِلم وغيره، وساعةٌ من الزمان، وإدراك الشيء، وظَرف من الظروف', statement_en = 'four core meanings: slowness and things like it, such as patience; an hour of time; a thing coming ripe; and a vessel', note_md = 'Marker: أصول أربعة. Corrected: old quote ran across two blocks; the other three (an hour, ripening, a vessel) are in blk_mqy_866fdb7bdad29b80. Was: «الهمزة والنون وما بعدهما من المعتل، لـه أصول أربعة: البُطء وما أشبهه مِن الحِلم ». Reading: slowness, hour of time, coming due, vessel. Other core meanings in his text: «وساعةٌ من الزمان، وإدراك الشيء، وظَرف من الظروف» (next block, Maqāyīs p.542–543). Weak-aṣl fix 2026-10-07: was «الهمزة والنون وما بعدهما من المعتل، لـه أصول أربعة: البُطء وما أشبهه مِن الحِلم وغيره» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_450263427296a614 p.24. Continues in blk_mqy_866fdb7bdad29b80 p.24.', updated_at = datetime('now')
 WHERE id = 'ASL:اني:maqayis_lugha' AND statement_ar IS 'الهمزة والنون وما بعدهما من المعتل، لـه أصول أربعة: البُطء وما أشبهه مِن الحِلم وغيره';

-- حجج
UPDATE ar_ling_root_asl SET statement_ar = 'الحاء والجيم أصولٌ أربعة. فالأول القصد، وكل قَصْدٍ حجٌّ … والأصل الآخر: الحِجَّة وهي السّنَة … والأصل الثالث: الحِجَاجُ، وهو العظْم المستدير حَولَ العَين … والأصل الرابع: الحَجْحَجة النُّكوص', statement_en = 'four core meanings: heading for a place (every such aiming is a ḥajj); a year; the round bone around the eye; and drawing back', note_md = 'Marker: أصول أربعة. Corrected: old quote joined two blocks; kept the head block only. Was: «الحاء والجيم أصولٌ أربعة. فالأول القصد، وكل قَصْدٍ حجٌّ. ثم اختُصَّ بهذا الاسمِ ». Weak-aṣl fix 2026-10-07: was «الحاء والجيم أصولٌ أربعة. فالأول القصد، وكل قَصْدٍ حجٌّ» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_947153fa4c0ec0ae p.1. Continues in blk_mqy_c6e76eaa1bd0e867 p.1, blk_mqy_0f55e86ec355651a p.1, blk_mqy_b7a5fb7e540cc90d p.1.', updated_at = datetime('now')
 WHERE id = 'ASL:حجج:maqayis_lugha' AND statement_ar IS 'الحاء والجيم أصولٌ أربعة. فالأول القصد، وكل قَصْدٍ حجٌّ';

