-- ربب
UPDATE ar_ling_root_asl SET statement_ar = 'الراء والباء يدلُّ على أُصولٍ. فالأول إصلاح الشيءِ والقيامُ عليه … والأصل الآخرُ لُزوم الشيءِ والإقامةُ عليه … والأصل الثالث: ضمُّ الشيء للشَّيء', statement_en = 'three core meanings: setting a thing right and looking after it; staying with a thing and keeping to it; and joining one thing to another', note_md = 'Marker: أصول + فالأوّل. Corrected: old quote ran across two blocks; «فالرّبّ: المالك…» is in blk_mqy_9d9484e4e0b1c069. Was: «الراء والباء يدلُّ على أُصولٍ. فالأول إصلاح الشيءِ والقيامُ عليه. فالرّبُّ: الما». Primary: Owner and caretaker shared; Ibn Fāris gives the clearest root statement. Weak-aṣl fix 2026-10-07: was «الراء والباء يدلُّ على أُصولٍ. فالأول إصلاح الشيءِ والقيامُ عليه» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_5ab0b7d16e4c0a5b p.28. Continues in blk_mqy_956f041ca4971765 p.28, blk_mqy_04581bb346b2bf75 p.28.', updated_at = datetime('now')
 WHERE id = 'ASL:ربب:maqayis_lugha' AND statement_ar IS 'الراء والباء يدلُّ على أُصولٍ. فالأول إصلاح الشيءِ والقيامُ عليه';

