UPDATE ar_ling_root_asl SET statement_ar = 'الباء والكاف والراء أصلٌ واحدٌ يرجع إليه فرعان هما منه. فالأوّل أوّلُ الشيء وبَدْؤُه. والثاني مشتقٌّ منه، والثالث تشبيه … فمنه البَكْر من الإبل، ما لم يَبْزُلْ بَعْدُ … وأما الثالث فالبَكَْرَةُ التي يُسْتَقَى عليها', statement_en = 'one core meaning with two branches: the start of a thing; from it, a young camel; and, by likeness, the pulley for drawing water', note_md = 'Marker: أصل واحد + فالأوّل. Primary: Both books say ''first/beginning''; Ibn Fāris is earlier and says it plainly. Weak-aṣl fix 2026-10-07: was «الباء والكاف والراء أصلٌ واحدٌ يرجع إليه فرعان هما منه. فالأوّل أوّلُ الشيء وبَدْؤُه» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_9666c36883a0227b p.30. Continues in blk_mqy_be11964602c2ec29 p.30, blk_mqy_0ffb07bc567dd88c p.30.', updated_at = datetime('now')
 WHERE id = 'ASL:بكر:maqayis_lugha' AND statement_ar IS 'الباء والكاف والراء أصلٌ واحدٌ يرجع إليه فرعان هما منه. فالأوّل أوّلُ الشيء وبَدْؤُه';

-- خرص
UPDATE ar_ling_root_asl SET statement_ar = 'الخاء والراء والصاد أصولٌ متباينة جدَّاً … فالأوّل الخَرْص، وهو حَزْرُ الشَّيء … وأصلٌ آخر، يقال للحَلْقة من الذَّهب خُرْصٌ … وأصلٌ آخر، وهو كل ذي شُعْبَةٍ من الشَّيء ذي الشُّعَب … وأصلٌ آخر، وهو الخَرَصُ، وهو صفة الجائع المقرور', statement_en = 'four very different core meanings: guessing a thing''s amount; a gold ring; anything that branches (an inlet, a twig, a spear); and being hungry and cold', block_id = 'blk_mqy_dbf6cd5afd059fbf', note_md = 'Marker: أصول متباينة → فالأوّل. Corrected: old quote was the second (gold ring) root; head block only counts the roots. Was: «أصلٌ آخر، يقال للحَلْقة من الذَّهب خُرْصٌ». Reading: estimating by guess, gold ring, branch, shoot, hungry and cold. Weak-aṣl fix 2026-10-07: was «فالأوّل الخَرْص، وهو حَزْرُ الشَّيء، يقال خَرَصْتُ النَّخْلَ، إذا حَزَرْتَ ثمرَه» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_dbf6cd5afd059fbf p.6. Continues in blk_mqy_ebc23f8f3c41418a p.6, blk_mqy_b30425af93bc6cab p.6, blk_mqy_6d90592cb5fd9c44 p.6, blk_mqy_5d697cbcda53583a p.6.', updated_at = datetime('now')
