UPDATE ar_ling_root_asl SET statement_ar = 'الشين والميم واللام أصلان منقاسان مطّردان، كل واحدٍ منهما في معناه وبابه … فالأوّل يدلُّ على دَوَران الشيء بالشيء وأخْذِهِ إيّاه من جوانبه … والأصل الثاني يدلُّ على الجانب الذي يخالف اليمين', statement_en = 'two core meanings: going round a thing and holding it from all sides; and the side opposite the right (the left)', block_id = 'blk_mqy_210c690931061eaa', note_md = 'Marker: فالأوّل. Corrected: head (blk_mqy_210c690931061eaa) only counts two aṣls; second aṣl is in blk_mqy_01f660c21110b774: «والأصل الثاني يدلُّ على الجانب الذي يخالف اليمين» (the left side). Was: «أصلان منقاسان مطّردان، كل واحدٍ منهما في معناه وبابه». Primary: Only row. Weak-aṣl fix 2026-10-07: was «فالأوّل يدلُّ على دَوَران الشيء بالشيء وأخْذِهِ إيّاه من جوانبه» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_210c690931061eaa p.23. Continues in blk_mqy_fe952668c4626abc p.23, blk_mqy_01f660c21110b774 p.23.', updated_at = datetime('now')
