UPDATE ar_ling_root_asl SET statement_ar = 'الشين والطاء والهمزة فيه كلمتان: إحداهما الشَّطْء شَطءُ النَّبات، وهو ما خرج من حول الأصل … والأصل شاطئ الوادي: جانبه', statement_en = 'two words: the shoots a plant puts out around its base; and the bank of a valley (its side)', note_md = 'Marker: أصل (Ibn Fāris head sentence). Primary: Only book with an aṣl row here so far; Ibn Fāris states it outright. Weak-aṣl fix 2026-10-07: was «الشين والطاء والهمزة فيه كلمتان: إحداهما الشَّطْء شَطءُ النَّبات، وهو ما خرج من حول الأصل، والجمع أشطاء» — named fewer meanings than announced; now names each core meaning in his words. Starts blk_mqy_3532ee26abe4e8db p.22. Continues in blk_mqy_4a28c2fd18227a4c p.22.', updated_at = datetime('now')
